arguments.command:
cd /app/submission && rm -rf __pycache__ && ls -la && find /app/submission | wc -l && python3 - <<'EOF'
import os, stat
root='/app/submission'
probs=[]
for dp, dn, fn in os.walk(root):
    for name in dn + fn:
        p=os.path.join(dp,name)
        st=os.lstat(p)
        m=st.st_mode
        if stat.S_ISLNK(m): probs.append(("symlink",p))
        elif stat.S_ISDIR(m):
            pass
        elif stat.S_ISREG(m):
            if st.st_nlink!=1: probs.append(("nlink",p,st.st_nlink))
        else: probs.append(("special",p,oct(m)))
    for name in dn:
        pass
print("compliance problems:", probs)
print("entries:", sum(len(x) for _,x,_ in os.walk(root)) , "dirs+files")
EOF
python3 /app/examples/smoke.py /app/submission/planner.py
